import twilio from 'twilio';
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';

// Get Twilio credentials
function getTwilioCredentials() {
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;

  if (!accountSid || !authToken) {
    console.error('Error: Twilio credentials not found in environment.');
    console.error('Required: TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN');
    process.exit(1);
  }

  return { accountSid, authToken };
}

// Get call status
async function getCallStatus(callSid) {
  const { accountSid, authToken } = getTwilioCredentials();
  const client = twilio(accountSid, authToken);

  try {
    const call = await client.calls(callSid).fetch();

    console.log('\n=== Call Status ===');
    console.log(`Call SID: ${call.sid}`);
    console.log(`Status: ${call.status}`);
    console.log(`To: ${call.to}`);
    console.log(`From: ${call.from}`);
    console.log(`Direction: ${call.direction}`);
    console.log(`Duration: ${call.duration ? `${call.duration}s` : 'N/A'}`);
    console.log(`Start Time: ${call.startTime || 'N/A'}`);
    console.log(`End Time: ${call.endTime || 'N/A'}`);

    if (call.price) {
      console.log(`Price: ${call.price} ${call.priceUnit}`);
    }

    // Status descriptions
    const statusDescriptions = {
      queued: 'Call is waiting to be initiated',
      ringing: 'Call is ringing',
      'in-progress': 'Call is currently active',
      completed: 'Call completed successfully',
      failed: 'Call failed to connect',
      busy: 'Number was busy',
      'no-answer': 'No one answered the call',
      canceled: 'Call was canceled'
    };

    if (statusDescriptions[call.status]) {
      console.log(`\nDescription: ${statusDescriptions[call.status]}`);
    }

    return call;
  } catch (error) {
    console.error('\n✗ Failed to fetch call status');
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
}

// CLI
const argv = yargs(hideBin(process.argv))
  .usage('Usage: $0 <call-sid>')
  .demandCommand(1, 'You must provide a call SID')
  .example('$0 CAxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx')
  .help()
  .argv;

getCallStatus(argv._[0]);

#!/usr/bin/env node

import twilio from 'twilio';
import yargs from 'yargs';
import { hideBin } from 'yargs/helpers';
import { readdirSync, readFileSync, existsSync } from 'fs';
import { join } from 'path';

// Get Twilio credentials
function getTwilioCredentials() {
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;

  if (!accountSid || !authToken) {
    console.error('Error: Twilio credentials not found in environment.');
    console.error('Required: TWILIO_ACCOUNT_SID, TWILIO_AUTH_TOKEN');
    process.exit(1);
  }

  return { accountSid, authToken };
}

// Get local logs
function getLocalLogs(days, limit) {
  const logsDir = '/job/logs/calls';

  if (!existsSync(logsDir)) {
    return [];
  }

  const logs = [];
  const dates = readdirSync(logsDir).sort().reverse();

  for (const date of dates) {
    // Check if within days limit
    const logDate = new Date(date);
    const daysDiff = Math.floor((Date.now() - logDate.getTime()) / (1000 * 60 * 60 * 24));

    if (daysDiff > days) continue;

    const dateDir = join(logsDir, date);
    const files = readdirSync(dateDir)
      .filter(f => f.endsWith('.json'))
      .sort()
      .reverse();

    for (const file of files) {
      if (logs.length >= limit) break;

      const logPath = join(dateDir, file);
      const log = JSON.parse(readFileSync(logPath, 'utf8'));
      log._date = date;
      log._file = file;
      logs.push(log);
    }

    if (logs.length >= limit) break;
  }

  return logs;
}

// Get Twilio call logs
async function getTwilioLogs(options) {
  const { accountSid, authToken } = getTwilioCredentials();
  const client = twilio(accountSid, authToken);

  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - options.days);

    const params = {
      startTime: startDate,
      limit: options.limit
    };

    if (options.status) {
      params.status = options.status;
    }

    const calls = await client.calls.list(params);

    console.log(`\n=== Twilio Call Logs (Last ${options.days} days) ===\n`);

    if (calls.length === 0) {
      console.log('No calls found.');
      return;
    }

    for (const call of calls) {
      console.log(`Call SID: ${call.sid}`);
      console.log(`  To: ${call.to}`);
      console.log(`  From: ${call.from}`);
      console.log(`  Status: ${call.status}`);
      console.log(`  Duration: ${call.duration ? `${call.duration}s` : 'N/A'}`);
      console.log(`  Start: ${call.startTime || 'N/A'}`);
      if (call.price) {
        console.log(`  Price: ${call.price} ${call.priceUnit}`);
      }
      console.log('');
    }

    console.log(`Total calls: ${calls.length}`);

  } catch (error) {
    console.error('\n✗ Failed to fetch call logs');
    console.error(`Error: ${error.message}`);
    process.exit(1);
  }
}

// Display local logs
function displayLocalLogs(options) {
  const logs = getLocalLogs(options.days, options.limit);

  console.log(`\n=== Local Call Logs (Last ${options.days} days) ===\n`);

  if (logs.length === 0) {
    console.log('No local logs found.');
    return;
  }

  for (const log of logs) {
    console.log(`Date: ${log._date}`);
    console.log(`File: ${log._file}`);
    console.log(`  Call SID: ${log.callSid}`);
    console.log(`  To: ${log.to}`);
    console.log(`  From: ${log.from}`);
    if (log.template) {
      console.log(`  Template: ${log.template}`);
    }
    console.log(`  Status: ${log.status}`);
    console.log(`  Time: ${new Date(log.timestamp).toLocaleString()}`);
    console.log('');
  }

  console.log(`Total logs: ${logs.length}`);
}

// CLI
const argv = yargs(hideBin(process.argv))
  .usage('Usage: $0 [options]')
  .option('days', {
    alias: 'd',
    type: 'number',
    description: 'Number of days to look back',
    default: 1
  })
  .option('limit', {
    alias: 'l',
    type: 'number',
    description: 'Maximum number of results',
    default: 20
  })
  .option('status', {
    alias: 's',
    type: 'string',
    description: 'Filter by status',
    choices: ['queued', 'ringing', 'in-progress', 'completed', 'failed', 'busy', 'no-answer', 'canceled']
  })
  .option('source', {
    type: 'string',
    description: 'Log source (local or twilio)',
    choices: ['local', 'twilio'],
    default: 'local'
  })
  .example('$0', 'Show local logs from last 24 hours')
  .example('$0 --days 7 --limit 50', 'Show local logs from last 7 days')
  .example('$0 --source twilio --status completed', 'Show completed calls from Twilio')
  .help()
  .argv;

if (argv.source === 'twilio') {
  getTwilioLogs(argv);
} else {
  displayLocalLogs(argv);
}

import { Octokit } from '@octokit/rest';

// Initialize GitHub client
export function getGitHubClient() {
  const token = process.env.DEPLOYMENT_GITHUB_TOKEN || process.env.GH_TOKEN;

  if (!token) {
    throw new Error('GitHub token not found. Set DEPLOYMENT_GITHUB_TOKEN or GH_TOKEN in LLM_SECRETS.');
  }

  return new Octokit({ auth: token });
}

// Get workflow runs for a repository
export async function getWorkflowRuns(owner, repo, options = {}) {
  const octokit = getGitHubClient();

  const params = {
    owner,
    repo,
    per_page: options.limit || 10,
    status: options.status || 'all'
  };

  if (options.workflow) {
    // Get workflow ID first
    const { data: workflows } = await octokit.actions.listRepoWorkflows({
      owner,
      repo
    });

    const workflow = workflows.workflows.find(w => 
      w.name === options.workflow || w.path.includes(options.workflow)
    );

    if (workflow) {
      params.workflow_id = workflow.id;
    }
  }

  const { data } = await octokit.actions.listWorkflowRunsForRepo(params);
  return data.workflow_runs;
}

// Get specific workflow run
export async function getWorkflowRun(owner, repo, runId) {
  const octokit = getGitHubClient();

  const { data: run } = await octokit.actions.getWorkflowRun({
    owner,
    repo,
    run_id: runId
  });

  return run;
}

// Get workflow run logs
export async function getWorkflowLogs(owner, repo, runId) {
  const octokit = getGitHubClient();

  try {
    const { data } = await octokit.actions.downloadWorkflowRunLogs({
      owner,
      repo,
      run_id: runId
    });

    return data;
  } catch (error) {
    console.error(`Failed to get logs: ${error.message}`);
    return null;
  }
}

// Get jobs for a workflow run
export async function getWorkflowJobs(owner, repo, runId) {
  const octokit = getGitHubClient();

  const { data } = await octokit.actions.listJobsForWorkflowRun({
    owner,
    repo,
    run_id: runId
  });

  return data.jobs;
}

// Extract error from workflow jobs
export async function extractError(owner, repo, runId) {
  const jobs = await getWorkflowJobs(owner, repo, runId);
  const failedJobs = jobs.filter(j => j.conclusion === 'failure');

  if (failedJobs.length === 0) {
    return { error: 'No failed jobs found', category: 'unknown' };
  }

  const errors = [];

  for (const job of failedJobs) {
    const failedSteps = job.steps.filter(s => s.conclusion === 'failure');

    for (const step of failedSteps) {
      errors.push({
        job: job.name,
        step: step.name,
        error: step.conclusion
      });
    }
  }

  // Categorize error
  const category = categorizeError(errors);

  return {
    error: formatErrors(errors),
    category,
    jobs: failedJobs.map(j => ({
      name: j.name,
      conclusion: j.conclusion,
      started_at: j.started_at,
      completed_at: j.completed_at
    }))
  };
}

// Categorize error type
function categorizeError(errors) {
  const errorText = JSON.stringify(errors).toLowerCase();

  if (errorText.includes('test') || errorText.includes('spec')) {
    return 'test_failure';
  }
  if (errorText.includes('build') || errorText.includes('compile')) {
    return 'build_error';
  }
  if (errorText.includes('dependency') || errorText.includes('package')) {
    return 'dependency_issue';
  }
  if (errorText.includes('timeout')) {
    return 'timeout';
  }
  if (errorText.includes('config') || errorText.includes('environment')) {
    return 'configuration_error';
  }

  return 'unknown';
}

// Format errors for display
function formatErrors(errors) {
  return errors.map(e => `${e.job} / ${e.step}: ${e.error}`).join('\n');
}

// Create a pull request
export async function createPullRequest(owner, repo, options) {
  const octokit = getGitHubClient();

  const { data: pr } = await octokit.pulls.create({
    owner,
    repo,
    title: options.title,
    body: options.body,
    head: options.branch,
    base: options.base || 'main'
  });

  return pr;
}

// List workflows
export async function listWorkflows(owner, repo) {
  const octokit = getGitHubClient();

  const { data } = await octokit.actions.listRepoWorkflows({
    owner,
    repo
  });

  return data.workflows;
}

// Check if deployment should be auto-fixed
export function shouldAutoFix(run, config) {
  if (!config?.auto_fix?.enabled) return false;

  // Check if branch is protected
  const protectedBranches = config.safety?.require_approval_for || [];
  if (protectedBranches.includes(run.head_branch)) {
    return false;
  }

  // Check if workflow is in allowed list
  const allowedWorkflows = config.auto_fix?.allowed_workflows;
  if (allowedWorkflows && !allowedWorkflows.includes(run.name)) {
    return false;
  }

  return true;
}

import ExcelJS from 'exceljs';
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { dirname } from 'path';

// Get tracking file path
function getTrackingFile() {
  const configPath = '/job/operating_system/DEPLOYMENT_MONITOR.json';

  if (existsSync(configPath)) {
    const config = JSON.parse(readFileSync(configPath, 'utf8'));
    return config.tracking?.file;
  }

  return process.env.DEPLOYMENT_TRACKING_FILE || '/job/logs/deployments/tracking.xlsx';
}

// Initialize tracking workbook
async function initWorkbook() {
  const filePath = getTrackingFile();
  const workbook = new ExcelJS.Workbook();

  if (existsSync(filePath)) {
    await workbook.xlsx.readFile(filePath);
  } else {
    // Create new workbook with headers
    const worksheet = workbook.addWorksheet('Deployments');

    worksheet.columns = [
      { header: 'Timestamp', key: 'timestamp', width: 20 },
      { header: 'Repository', key: 'repository', width: 30 },
      { header: 'Workflow', key: 'workflow', width: 30 },
      { header: 'Status', key: 'status', width: 15 },
      { header: 'Duration (s)', key: 'duration', width: 15 },
      { header: 'Commit', key: 'commit', width: 15 },
      { header: 'Branch', key: 'branch', width: 20 },
      { header: 'Error', key: 'error', width: 50 },
      { header: 'Category', key: 'category', width: 20 },
      { header: 'Fix Applied', key: 'fix_applied', width: 15 },
      { header: 'Auto Fixed', key: 'auto_fixed', width: 15 },
      { header: 'Run ID', key: 'run_id', width: 15 }
    ];

    // Style header row
    worksheet.getRow(1).font = { bold: true };
    worksheet.getRow(1).fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF366092' }
    };
    worksheet.getRow(1).font = { color: { argb: 'FFFFFFFF' }, bold: true };
  }

  return { workbook, filePath };
}

// Add deployment record
export async function trackDeployment(data) {
  const { workbook, filePath } = await initWorkbook();
  const worksheet = workbook.getWorksheet('Deployments') || workbook.addWorksheet('Deployments');

  // Ensure directory exists
  mkdirSync(dirname(filePath), { recursive: true });

  // Calculate duration
  let duration = null;
  if (data.started_at && data.completed_at) {
    const start = new Date(data.started_at);
    const end = new Date(data.completed_at);
    duration = Math.round((end - start) / 1000);
  }

  // Add row
  worksheet.addRow({
    timestamp: data.timestamp || new Date().toISOString(),
    repository: data.repository,
    workflow: data.workflow,
    status: data.status,
    duration: duration,
    commit: data.commit?.substring(0, 7),
    branch: data.branch,
    error: data.error || '',
    category: data.category || '',
    fix_applied: data.fix_applied ? 'Yes' : 'No',
    auto_fixed: data.auto_fixed ? 'Yes' : 'No',
    run_id: data.run_id
  });

  // Apply conditional formatting for status
  const lastRow = worksheet.lastRow;
  const statusCell = lastRow.getCell('status');

  if (data.status === 'success' || data.status === 'completed') {
    statusCell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FF90EE90' }
    };
  } else if (data.status === 'failure' || data.status === 'failed') {
    statusCell.fill = {
      type: 'pattern',
      pattern: 'solid',
      fgColor: { argb: 'FFFF6B6B' }
    };
  }

  // Save workbook
  await workbook.xlsx.writeFile(filePath);

  console.log(`✓ Deployment tracked: ${filePath}`);

  return filePath;
}

// Get deployment history
export async function getDeploymentHistory(options = {}) {
  const { workbook } = await initWorkbook();
  const worksheet = workbook.getWorksheet('Deployments');

  if (!worksheet) {
    return [];
  }

  const records = [];
  const now = new Date();
  const daysAgo = new Date(now - (options.days || 30) * 24 * 60 * 60 * 1000);

  worksheet.eachRow((row, rowNumber) => {
    if (rowNumber === 1) return; // Skip header

    const record = {
      timestamp: row.getCell('timestamp').value,
      repository: row.getCell('repository').value,
      workflow: row.getCell('workflow').value,
      status: row.getCell('status').value,
      duration: row.getCell('duration').value,
      commit: row.getCell('commit').value,
      branch: row.getCell('branch').value,
      error: row.getCell('error').value,
      category: row.getCell('category').value,
      fix_applied: row.getCell('fix_applied').value === 'Yes',
      auto_fixed: row.getCell('auto_fixed').value === 'Yes',
      run_id: row.getCell('run_id').value
    };

    // Filter by date
    const recordDate = new Date(record.timestamp);
    if (recordDate < daysAgo) return;

    // Filter by repository
    if (options.repository && record.repository !== options.repository) return;

    // Filter by status
    if (options.status && record.status !== options.status) return;

    records.push(record);
  });

  return records.reverse(); // Most recent first
}

// Generate deployment report
export async function generateReport(options = {}) {
  const records = await getDeploymentHistory(options);

  if (records.length === 0) {
    return {
      total: 0,
      success: 0,
      failed: 0,
      success_rate: 0,
      avg_duration: 0,
      auto_fixed: 0,
      categories: {}
    };
  }

  const total = records.length;
  const success = records.filter(r => r.status === 'success' || r.status === 'completed').length;
  const failed = records.filter(r => r.status === 'failure' || r.status === 'failed').length;
  const success_rate = Math.round((success / total) * 100);

  const durations = records.filter(r => r.duration).map(r => r.duration);
  const avg_duration = durations.length > 0 
    ? Math.round(durations.reduce((a, b) => a + b, 0) / durations.length)
    : 0;

  const auto_fixed = records.filter(r => r.auto_fixed).length;

  // Count by category
  const categories = {};
  records.forEach(r => {
    if (r.category) {
      categories[r.category] = (categories[r.category] || 0) + 1;
    }
  });

  return {
    total,
    success,
    failed,
    success_rate,
    avg_duration,
    auto_fixed,
    categories,
    records: options.include_records ? records : undefined
  };
}

// Save log to JSON
export function saveLog(type, data) {
  const date = new Date().toISOString().split('T')[0];
  const logDir = `/job/logs/deployments/${date}`;

  mkdirSync(logDir, { recursive: true });

  // Find next log number
  const files = require('fs').readdirSync(logDir);
  const logNumbers = files
    .filter(f => f.startsWith(`${type}-`) && f.endsWith('.json'))
    .map(f => parseInt(f.match(/(\d+)/)?.[1] || '0'))
    .filter(n => !isNaN(n));

  const nextNumber = logNumbers.length > 0 ? Math.max(...logNumbers) + 1 : 1;
  const filename = `${type}-${String(nextNumber).padStart(3, '0')}.json`;

  const logPath = `${logDir}/${filename}`;
  writeFileSync(logPath, JSON.stringify(data, null, 2));

  return logPath;
}

